-- Production: what the kitchen made, and stock it put on a shelf.
-- Design and the alternatives rejected: files/production-tracking-2026-09.md.
--
-- Generated by drizzle-kit, then READ, then extended by hand below the generated block.
--
-- The two replaced stock_movements checks compare movement_type::text, not the enum.
-- Postgres refuses to use an enum value inside the transaction that added it, and this
-- file does both. See the comment on stock_movements_cost_on_valued_inflow in
-- src/db/schema.ts - probed, not assumed.
--
-- Between the DROP and the re-ADD of those checks the ledger is briefly unguarded. That
-- is safe only because the migrator runs this whole file in one transaction, so no
-- other session can see the gap.
ALTER TYPE "public"."movement_type" ADD VALUE 'production';--> statement-breakpoint
CREATE TABLE "production_runs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"recipe_id" uuid NOT NULL,
	"produced_on" date NOT NULL,
	"batches_milli" bigint NOT NULL,
	"expected_yield_milli_base" bigint NOT NULL,
	"actual_yield_milli_base" bigint NOT NULL,
	"yield_unit_type" "unit_type" NOT NULL,
	"batch_cost_paise" bigint,
	"note" text,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "production_runs_batches_positive" CHECK ("production_runs"."batches_milli" > 0),
	CONSTRAINT "production_runs_expected_positive" CHECK ("production_runs"."expected_yield_milli_base" > 0),
	CONSTRAINT "production_runs_actual_nonneg" CHECK ("production_runs"."actual_yield_milli_base" >= 0),
	CONSTRAINT "production_runs_cost_nonneg" CHECK ("production_runs"."batch_cost_paise" is null or "production_runs"."batch_cost_paise" >= 0)
);
--> statement-breakpoint
