-- ---- by hand: production_runs is append-only, like the ledger it pairs with ----------
--
-- Every figure in a run is a snapshot, and each run is paired with stock_movements rows
-- that can never be edited. Editing the run would leave the two describing different
-- batches. A mistake is corrected with a reversing run, the same answer 0006 gives the
-- ledger - and the same maintenance hatch, so scripts/clean-test-data.ts can still drop
-- a whole test tenant:
--
--     set local app.ledger_maintenance = 'on';
CREATE OR REPLACE FUNCTION production_runs_append_only() RETURNS trigger AS $$
BEGIN
  IF current_setting('app.ledger_maintenance', true) = 'on' THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION
    'production_runs is append-only: % attempted on run %. Log a correcting run instead.',
    TG_OP, OLD.id
    USING ERRCODE = 'restrict_violation';
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER production_runs_no_update
  BEFORE UPDATE ON "production_runs"
  FOR EACH ROW EXECUTE FUNCTION production_runs_append_only();--> statement-breakpoint
CREATE TRIGGER production_runs_no_delete
  BEFORE DELETE ON "production_runs"
  FOR EACH ROW EXECUTE FUNCTION production_runs_append_only();
